import{useEffect,useState}from"react";import type{RouteConfig}from"@mercurjs/dashboard-sdk";import"../../spike/vendor-spike.css";declare const __BACKEND_URL__:string
export const config:RouteConfig={label:"الكوبونات",rank:61};type Product={id:string;title:string};const base=()=>String(__BACKEND_URL__||"http://localhost:9000").replace(/\/$/,"");async function api(p:string,i?:RequestInit){const r=await fetch(base()+p,{credentials:"include",...i,headers:{...(i?.body?{"content-type":"application/json"}:{}),...(i?.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||`HTTP ${r.status}`);return d}
export default function Page(){const[products,setProducts]=useState<Product[]>([]),[rows,setRows]=useState<any[]>([]),[code,setCode]=useState(""),[percent,setPercent]=useState("10"),[scope,setScope]=useState<"product"|"store">("product"),[couponProduct,setCouponProduct]=useState(""),[msg,setMsg]=useState("");const load=async()=>{const[p,d]=await Promise.all([api('/vendor/products?limit=200&fields=id,title'),api('/vendor/spike/discounts')]);setProducts(p.products||[]);setRows((d.discounts||[]).filter((x:any)=>x.request_type==='coupon'))};useEffect(()=>{load().catch(e=>setMsg(e.message))},[]);const send=async()=>{if(!code.trim())return setMsg('اكتب كود الكوبون');if(scope==='product'&&!couponProduct)return setMsg('اختر المنتج');const pct=Math.max(1,Math.min(99,Number(percent)||0));await api('/vendor/spike/discounts',{method:'POST',body:JSON.stringify({request_type:'coupon',coupon_code:code,coupon_percentage:pct,target_type:scope,target_id:scope==='store'?'':couponProduct,product_title:scope==='store'?'كامل المتجر':products.find(p=>p.id===couponProduct)?.title})});setCode('');setCouponProduct('');setMsg('تم إرسال الكوبون للأدمن للموافقة');load()};const del=async(id:string)=>{if(!confirm('حذف الكوبون؟ إذا كان فعالاً سيتم إلغاؤه.'))return;try{await api(`/vendor/spike/discounts?id=${encodeURIComponent(id)}`,{method:'DELETE'});setMsg('تم حذف الكوبون');load()}catch(e:any){setMsg(e.message)}};return <div className="spike-page" dir="rtl"><div className="spike-card"><h1 className="spike-title">الكوبونات</h1>{msg&&<div className="spike-review-hint">{msg}</div>}<div className="spike-vendor-grid"><label>الكود<input value={code} onChange={e=>setCode(e.target.value.toUpperCase())}/></label><label>النسبة %<input type="number" min="1" max="99" value={percent} onChange={e=>setPercent(e.target.value)}/></label><label>يطبق على<select value={scope} onChange={e=>setScope(e.target.value as any)}><option value="product">منتج محدد</option><option value="store">كامل المتجر</option></select></label>{scope==='product'&&<label>المنتج<select value={couponProduct} onChange={e=>setCouponProduct(e.target.value)}><option value="">اختر</option>{products.map(p=><option key={p.id} value={p.id}>{p.title}</option>)}</select></label>}</div><button className="spike-btn" onClick={send}>إرسال الكوبون للموافقة</button><h2 style={{marginTop:28}}>الكوبونات السابقة</h2><table className="spike-table"><thead><tr><th>الكود</th><th>النسبة</th><th>النطاق</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><b>{r.coupon_code}</b></td><td>{r.coupon_percentage}%</td><td>{r.target_type==='store'?'كامل المتجر':r.product_title||'منتج'}</td><td>{r.status==='pending'?'بانتظار الموافقة':r.status==='approved'?'مقبول':'مرفوض'}</td><td><button className="spike-btn danger" onClick={()=>del(r.id)}>حذف</button></td></tr>)}</tbody></table></div></div>}
